    "light_of_atoms_as": "气态原子发出的光，从 380 nm 的紫光到 750 nm 的红光：吸收光谱，即白光通过时，在彩虹中被吸收的颜色处出现暗线；发射光谱，即加热或放电时，只发出这些颜色，在黑色背景上呈亮线。每种元素都有自己独特的谱线，就像指纹：氦就是先在太阳中发现、后在地球上发现的。按 NIST 列出最强的谱线，越强越宽；原子在此范围内没有谱线时，显示其离子的。点击可切换另一种。",
