    "open_mode": "打开方式",
    "what_toolbar_icon_and": "工具栏图标和 Alt+S 打开的内容：固定，即图标下方的弹出窗口；分离，即在独立窗口中的计算器，窗口可随之放大缩小；或高级，即在大窗口中弹出的计算器，工具排列在侧边，其“收回”按钮可将其带回分离模式。“启动”会打开所选的一种；分离模式和高级模式也在工具栏图标的菜单中，分离模式还在页面按钮上。",
