    "removes_what_before_cursor": "删除光标前面的内容。回到末尾后（[→] 或 [End]），算式会重新计算，计算器照常继续；= 可在任何位置结束它。在结果之后，[←] 再次输入其算式，[→] 把光标放在其开头。",
