    "d_or_changes_mode_3": "[d 或 °] 将模式切换为以百分度表示三角函数，一整圈为 400，直角为 100：sin 100 是 1。该键依次从 Rad 到 Deg 到 Grad 再回到 Rad，并显示它将切换到的下一个单位。",
    "f_turns_fraction_mode": "[f] 开启和关闭分数模式。开启时（显示屏中有 FRAC），每个除法都会在输入时画成分数：1 ÷ 2 + 1 ÷ 3 显示为 ½ + ⅓，= 显示 5/6。凡能表示为分数的结果都显示为分数，最多 10 位；不是分数的数，如 π 或 √2，保持为小数。复制时分数写作 5/6。该模式一直开启，直到您再次点击",
