    "o_goes_on_to": "[o] 切换到结果的下一种记数法：常规、Fix (1500.00)、Sci (1.50e+3)、Eng (1.50e+3，10 的幂以 3 为步长)，然后又回到常规。开启时，显示屏显示 FIX 2、SCI 2 或 ENG 2，若小数位数为自动，则只显示 SCI 和 ENG：每个结果按需要显示位数 (1.5e+3)，Fix 与常规相同。小数位数和千位分隔符在“选项”标签页中设置，该标签页紧随此键之后。",
