    "whole_number_at_or_4": "。不小于该数的整数：ceil(2.1) 是 3，ceil(-2.1) 是 -2。",
    "about_precision": "关于精度",
    "calculator_operates_with_precision": "本计算器的精度约为 15 位有效数字（仅此而已）。这是由 JavaScript 处理浮点数的方式造成的。",
    "isn_t_actually_javascript": "这其实不是 JavaScript 的特性，而是 IEEE 754 标准规定浮点数在内存中存储方式所带来的特性。JavaScript 要求每个数都是这类 64 位值之一，任何使用它们的语言，如 C、Java 或 Python，也都有这个“特性”。",
    "results_shown_with_13": "结果显示 13 位有效数字，所以这些微小的舍入误差不会显现：0.1 + 0.2 显示 0.3，而不是 0.30000000000000004。以度为单位的角度在应得精确值时给出精确值：sin 180 是 0，cos 60 是 0.5。",
    "problem_javascript_uses_64": "问题在于 JavaScript 用 64 位数据存储每个数，这 64 位可以容纳 18446744073709551616 种不同的位模式：1 位符号、11 位指数和 52 位有效数字。这覆盖了从约 –1.7976931348623157e+308 到 1.7976931348623157e+308 的数值，最小的规格化数为 2.2250738585072014e–308，更小的可达 5e–324。",
    "smaller_precision_value_with": "用一个精度较低、其中几位作指数的值，就能容纳这个范围（也可以用 16 位做到，范围更小、精度更低）。其结果是，它可以近似任何范围内的值，却无法精确表示所有的值，因为就实数而言，任意两个给定值之间都有无穷多个值。",
    "as_part_of_your": "在您的计算中，显然这个值的内部表示超出了可用的精度，您得到的是该值的近似值，而不是精确值。",
    "for_schools_and_organizations": "适用于学校和机构",
    "administrators_can_disable_specific": "管理员可以停用学生不得使用的或考试期间不得使用的特定计算器功能，包括公式、单位换算、图像、统计、求解、数、化学、物理、生物、分离模式，以及在每个网站上显示计算器按钮的选项。这些设置可通过 Google 管理控制台或 Chrome 政策，为所有受管理的学生集中配置。",
    "once_feature_disabled_immediately": "某项功能一旦被停用，会立即从计算器中移除，学生无法重新启用。该设置会被锁定，并显示消息“已被您的管理员关闭。”",
