    "largest_use_for_neon": "氖气最大的用途是广告灯牌。氖还用于制造高压指示灯，并与氦混合制成氦氖激光器。",
    "name_derives_from_greek_5": "名称来自希腊语 neos，意为“新的”。",
    "face_centred_cubic": "面心立方",
    "colourless_gas_glows_orange": "无色气体；在电场中发橙红光",
    "sodium": "钠",
    "sodium_used_in_production": "钠用于生产钛、氨基钠、氰化钠、过氧化钠和氢化钠。液态钠曾用作核反应堆的冷却剂。",
    "name_derives_from_english": "名称来自英语 soda 和拉丁语 sodanum（意为“头痛药”）。符号 Na 来自拉丁语 natrium，意为“泡碱”（英语中为 soda）。",
    "magnesium": "镁",
    "magnesium_burns_with_brilliant": "镁燃烧时发出耀眼的白光，用于烟花、信号弹和摄影闪光灯。",
    "name_derives_from_magnesia": "名称来自希腊东北部色萨利地区的 Magnesia 地区。",
    "shiny_grey_metal": "有光泽的灰色金属",
    "aluminium": "铝",
    "two_important_developments_in": "19 世纪 80 年代的两项重要进展大大提高了铝的产量。第一项是发明了从氧化铝中提取铝的新工艺。",
    "name_derives_from_latin_5": "名称来自拉丁语 alum 和 alumen，意为“涩的”，因为古罗马人把任何有涩味的物质都称为 alum。",
    "silvery_grey_metal": "银灰色金属",
    "silicon": "硅",
    "two_allotropes_of_silicon": "室温下硅有两种同素异形体：无定形硅和晶体硅。无定形硅为棕色粉末，晶体硅则有金属光泽，呈灰色。",
    "name_derives_from_latin_6": "名称来自拉丁语 silex 和 silicis，意为“燧石”。无定形硅由瑞典化学家贝采利乌斯于 1824 年发现。",
    "diamond_cubic": "金刚石立方",
    "crystalline_reflective_with_bluish": "晶体，有光泽，晶面略带蓝色",
    "phosphorus": "磷",
    "phosphorus_has_three_main": "磷有三种主要的同素异形体：白磷、红磷和黑磷。白磷有毒，接触空气时会自燃。",
    "name_derives_from_greek_6": "名称来自希腊语 phosphoros，意为“带来光明”，因为它能在黑暗中发光。",
    "white_body_centred_cubic": "白磷（α）：体心立方",
    "white_red_and_violet": "白磷、红磷和紫磷呈蜡状；黑磷有金属光泽",
    "sulfur": "硫",
    "most_of_sulfur_produced": "生产的大部分硫用于制造硫酸（H2SO4）。",
    "name_derives_from_latin_7": "名称来自拉丁语 sulphurium 和梵语 sulveri。硫曾被称为 brenne stone，意为“可燃的石头”，brimstone 一词即由此而来。",
    "s_orthorhombic": "α-S₈：正交",
    "lemon_yellow_solid": "柠檬黄色固体",
    "chlorine": "氯",
    "chlorine_commonly_used_as": "氯常用作消毒剂，用于使饮用水安全和处理游泳池。",
    "name_derives_from_greek_7": "名称来自希腊语 chloros，意为该元素的“淡绿色”或“黄绿色”。",
