    "pale_yellow_green_gas": "淡黄绿色气体",
    "argon": "氩",
    "argon_frequently_used_when": "需要惰性气氛时常使用氩。它被充入白炽灯和荧光灯中，防止氧气腐蚀灼热的灯丝。",
    "name_derives_from_greek_8": "名称来自希腊语 argos，意为“懒惰的”或“不活泼的”，因为它不与其他元素化合。",
