    "name_derives_from_english_2": "名称来自英语 potash 或 pot ashes（“草木灰”），因为它存在于苛性钾（KOH）中。",
    "calcium": "钙",
    "due_to_high_reactivity": "由于与常见物质反应性很强，金属钙的需求很少。它用于某些化学工艺中提炼钍、铀和锆。",
    "name_derives_from_latin_8": "名称来自拉丁语 calx，意为“石灰”（CaO）或“石灰石”（CaCO3），钙就是在其中发现的。",
