    "name_derives_from_latin_9": "名称来自拉丁语 scandia，即斯堪的纳维亚，这种矿物就是在那里发现的。",
    "titanium": "钛",
    "titanium_strong_light_metal": "钛是一种坚固而轻的金属。它与钢一样坚固，强度是铝的两倍，但比钢轻 45%，只比铝重 60%。",
    "name_derives_from_latin_10": "名称来自拉丁语 titans，即神话中的“大地的长子”泰坦。",
    "silvery_grey_white_metal": "银灰白色金属",
    "vanadium": "钒",
    "vanadium_corrosion_resistant_and": "钒耐腐蚀，有时用于为化学工业制造特殊管道。",
    "name_derives_from_scandinavian": "名称来自斯堪的纳维亚爱与美的女神 Freyja Vanadis，因为它有许多美丽多彩的化合物。",
    "blue_silver_grey_metal": "蓝银灰色金属",
    "chromium": "铬",
    "chromium_blue_white_metal": "铬是一种蓝白色金属，坚硬、脆，且非常耐腐蚀。",
    "name_derives_from_greek_9": "名称来自希腊语 chroma，意为“颜色”，因为铬的化合物色彩丰富。",
    "antiferromagnetic": "反铁磁性",
    "silvery_metal": "银色金属",
    "manganese": "锰",
