    "berkelium": "锫",
    "since_only_small_amounts": "由于迄今只制得少量的锫，它除基础科学研究外没有用途。它是制造更重元素的靶材：2009 年首次用锫-249 制得了鿬。",
    "berkelium_was_first_produced": "锫于 1949 年 12 月由加州大学伯克利分校的汤普森、西博格、斯特里特和吉奥索首次制得。",
    "californium": "锎",
    "californium_252_isotope_with": "锎-252 是一种半衰期约 2.6 年的同位素，是非常强的中子源。1 微克（0.000001 克）锎-252 每分钟产生 170,000,000 个中子。",
    "californium_was_first_produced": "锎于 1950 年由加州大学伯克利分校的汤普森、西博格、斯特里特和吉奥索首次制得。",
    "einsteinium": "锿",
